from fractions import Fraction
import numpy as np

def minor(A, i, j):
    return [A[k][:j] + A[k][j + 1:] for k in range(len(A)) if k != i]

def det(A):
    if len(A) == 1:
        return A[0][0]
    return sum((-1) ** j * A[0][j] * det(minor(A, 0, j)) for j in range(len(A)))

def paren(x):
    if x < 0:
        return f"({x})"
    return str(x)

def expand(label, A):
    n = len(A)
    print(f"{label}: {n}×{n}")
    if n == 1:
        print(f"  a 1×1 determinant is its entry: {A[0][0]}")
        return
    total = 0
    for j in range(n):
        sign = "+" if j % 2 == 0 else "-"
        m = det(minor(A, 0, j))
        term = (-1) ** j * A[0][j] * m
        total = total + term
        print(f"  {sign} a1{j + 1} · M1{j + 1} = {sign} {paren(A[0][j])} · {paren(m)} = {term}")
    print(f"  det = {total}, numpy: {round(np.linalg.det(A), 6)}")

expand("Case 1 · two by two", [[3, 8], [4, 6]])
expand("Case 2 · three by three", [[1, 2, 3], [4, 5, 6], [7, 8, 10]])
expand("Case 3 · a zero column", [[2, 0, 1], [3, 0, 5], [1, 4, 2]])
expand("Case 4 · triangular", [[2, 5, 1], [0, 3, 7], [0, 0, 4]])
expand("Case 5 · four by four", [[2, 0, 0, 1], [1, 3, 0, 0], [0, 1, 4, 0], [0, 0, 1, 5]])
expand("Case 6 · one parabola", [[1, 1, 1], [1, 2, 4], [1, 4, 16]])

